    },
    {
      "id": "TC-004",
      "title": "AUDIO PAUSE / ALARM PAUSE Key Functionality",
      "req_ids": ["RW-SW-78"],
      "kind": "positive",
      "preconditions": ["Alarm system initialized", "All alarms active"],
      "inputs": {"name": "pause_key", "value": "pressed"},
      "steps": ["Pause all active alarms", "Display alarm inactivation symbol"],
      "expected": ["All active alarms are paused for 60 seconds", "Alarm inactivation symbol is displayed"]
    },
    {
      "id": "TC-005",
      "title": "Apnea Alarm Indication",
      "req_ids": ["RW-SW-80"],
      "kind": "positive",
      "preconditions": ["Alarm system initialized", "No breath detected"],
      "inputs": {"name": "breath_detected", "value": "false"},
      "steps": ["Trigger apnea alarm", "Display 'APNEA ALARM' text"],
      "expected": ["Apnea alarm is triggered", "Text 'APNEA ALARM' is displayed"]
    },
    {
      "id": "TC-006",
      "title": "Breath Rate Alarm Indication",
      "req_ids": ["RW-SW-82"],
      "kind": "positive",
      "preconditions": ["Alarm system initialized", "Breath rate exceeded"],
      "inputs": {"name": "breath_rate", "value": "exceeded"},
      "steps": ["Trigger breath rate alarm", "Display 'HIGH BREATH RATE' text"],
      "expected": ["Breath rate alarm is triggered", "Text 'HIGH BREATH RATE' is displayed"]
    },
    {
      "id": "TC-007",
      "title": "Pressure Low Alarm Indication",
      "req_ids": ["RW-SW-84"],
      "kind": "positive",
      "preconditions": ["Alarm system initialized", "Pressure low detected"],
      "inputs": {"name": "pressure", "value": "low"},
      "steps": ["Trigger pressure low alarm", "Display 'LOW INSP P' text"],
      "expected": ["Pressure low alarm is triggered", "Text 'LOW INSP P' is displayed"]
    }
  ]
}
